package com.example.data

import com.example.model.*
import kotlin.math.abs

internal data class CountrySeed(
    val iso: String,
    val name: String,
    val capital: String,
    val continent: String,
    val currencyCode: String,
    val currencySymbol: String,
    val forexPerUsd: Double,
    val govType: GovType,
    val economicSystem: EconomicSystem,
    val powerStructure: PowerStructure,
    val upperChamber: String,
    val lowerChamber: String,
    val centralBank: String,
    val intelAgency: String,
    val gdpBillions: Double,
    val popMillions: Double,
    val mapX: Float,
    val mapY: Float,
    val bloc: String = "Non-Aligned",
    val agenda: String = "Sovereign Modernization"
)

internal fun CountrySeed.toCountry(playerHomeIso: String): Country {
    val hash = abs(iso.hashCode())
    val baseRel = if (iso == playerHomeIso) 100 else ((hash % 130) - 55).coerceIn(-90, 85)
    val stab = (58 + (hash % 38)).coerceIn(35, 97)
    val inf = when (economicSystem) {
        EconomicSystem.PLANNED -> 2.1 + (hash % 30) * 0.1
        EconomicSystem.MARKET -> 2.4 + (hash % 45) * 0.1
        else -> 3.0 + (hash % 55) * 0.1
    }
    return Country(
        iso = iso,
        name = name,
        capital = capital,
        continent = continent,
        currencyCode = currencyCode,
        currencySymbol = currencySymbol,
        forexPerUsd = forexPerUsd,
        govType = govType,
        economicSystem = economicSystem,
        powerStructure = powerStructure,
        upperChamberName = upperChamber,
        lowerChamberName = lowerChamber,
        centralBankName = centralBank,
        intelAgencyName = intelAgency,
        gdpBillionsUsd = gdpBillions,
        populationMillions = popMillions,
        treasuryBillionsUsd = (gdpBillions * 0.18).coerceAtLeast(0.4),
        stability = stab,
        inflationPct = inf,
        taxRatePct = if (economicSystem == EconomicSystem.PLANNED) 42.0 else 24.0 + (hash % 16),
        interestRatePct = 3.25 + (hash % 6) * 0.5,
        reserveRatioPct = 10.0 + (hash % 8),
        m0BillionsUsd = (gdpBillions * 0.12).coerceAtLeast(0.2),
        m1BillionsUsd = (gdpBillions * 0.45).coerceAtLeast(0.8),
        swiftConnected = iso !in setOf("KP", "IR", "RU", "CU", "SY"),
        bilateralRelation = baseRel,
        visaExemption = iso == playerHomeIso || baseRel >= 35,
        allianceBloc = bloc,
        nationalAgenda = agenda,
        mapX = mapX,
        mapY = mapY,
        fiveYearQuotaTargetGdp = gdpBillions * 1.18
    )
}

